    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Dashboard Admin | KantongKu</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7f5;font-family: 'Inter', sans-serif;color:#26352d}.top{background:#fff;padding:18px 7%;display:flex;justify-content:space-between;align-items:center;box-shadow:0 2px 12px #00000008}.brand{font-size:22px;font-weight:800;color:#18794e}button,.btn{background:#18794e;color:#fff;border:0;border-radius:9px;padding:10px 15px;cursor:pointer;font-weight:600;text-decoration:none;display:inline-block}.wrap{max-width:1150px;margin:35px auto;padding:0 22px}.welcome,.panel,.stat{background:#fff;border-radius:15px;padding:22px;box-shadow:0 5px 20px #183b2408}.welcome{margin-bottom:20px}.welcome p,.muted{color:#68756d;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin:20px 0}.stat span{display:block;color:#68756d;font-size:13px}.stat strong{display:block;margin-top:10px;font-size:23px;color:#18794e}.columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{margin-bottom:18px;overflow-x:auto}.panel h2{margin-top:0;font-size:18px}table{width:100%;border-collapse:collapse;min-width:380px}th,td{text-align:left;padding:11px 8px;border-bottom:1px solid #edf0ed;font-size:14px}th{color:#68756d;font-size:12px}.links{display:flex;gap:10px;flex-wrap:wrap}.status{padding:12px;background:#e4f5e9;color:#17663f;border-radius:8px;margin-bottom:16px}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}.columns{grid-template-columns:1fr}}@media(max-width:480px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><div class="brand">KantongKu <span style="font-size:12px;color:#68756d">ADMIN</span></div><form method="POST" action="{{ route('logout') }}">@csrf<button type="submit">Logout</button></form></header><main class="wrap">@if(session('success'))<div class="status">{{ session('success') }}</div>@endif<section class="welcome"><h1>Halo, {{ auth()->user()->name }}!</h1><p>Ringkasan sistem KantongKu. Pantau akun dan aktivitas pencatatan keuangan dari satu halaman.</p><div class="links"><a class="btn" href="{{ route('admin.users.index') }}">Kelola Pengguna</a></div></section><section class="grid"><div class="stat"><span>Total Mahasiswa</span><strong>{{ number_format($totalUsers) }}</strong></div><div class="stat"><span>Total Admin</span><strong>{{ number_format($totalAdmins) }}</strong></div><div class="stat"><span>Total Pemasukan Tercatat</span><strong>Rp {{ number_format($totalPemasukan,0,',','.') }}</strong></div><div class="stat"><span>Total Pengeluaran Tercatat</span><strong>Rp {{ number_format($totalPengeluaran,0,',','.') }}</strong></div></section><section class="columns"><div class="panel"><h2>Pengguna Terbaru</h2><table><thead><tr><th>Nama</th><th>Role</th><th>Terdaftar</th></tr></thead><tbody>@forelse($recentUsers as $user)<tr><td>{{ $user->name }}</td><td>{{ ucfirst($user->role) }}</td><td>{{ $user->created_at?->format('d/m/Y') }}</td></tr>@empty<tr><td colspan="3">Belum ada pengguna.</td></tr>@endforelse</tbody></table></div><div class="panel"><h2>Pemasukan Terbaru</h2><table><thead><tr><th>Nama</th><th>Pemilik</th><th>Jumlah</th></tr></thead><tbody>@forelse($recentPemasukan as $item)<tr><td>{{ $item->nama_pemasukan }}</td><td>{{ $item->user?->name ?? 'Akun dihapus' }}</td><td>Rp {{ number_format((float)$item->jumlah,0,',','.') }}</td></tr>@empty<tr><td colspan="3">Belum ada pemasukan.</td></tr>@endforelse</tbody></table></div><div class="panel"><h2>Pengeluaran Terbaru</h2><table><thead><tr><th>Nama</th><th>Pemilik</th><th>Jumlah</th></tr></thead><tbody>@forelse($recentPengeluaran as $item)<tr><td>{{ $item->nama_pengeluaran }}</td><td>{{ $item->user?->name ?? 'Akun dihapus' }}</td><td>Rp {{ number_format((float)$item->jumlah,0,',','.') }}</td></tr>@empty<tr><td colspan="3">Belum ada pengeluaran.</td></tr>@endforelse</tbody></table></div><div class="panel"><h2>Kontrol Admin</h2><p class="muted">Admin dapat melihat ringkasan agregat, meninjau aktivitas terbaru, dan mengelola akun. Data pemasukan dan pengeluaran tetap dimiliki masing-masing mahasiswa.</p><a class="btn" href="{{ route('admin.users.index') }}">Buka daftar pengguna</a></div></section></main></body></html>
